# frozen_string_literal: true

require "digest"
require "fileutils"
require "pathname"

module Branchout
  module Emitters
    # Shared, deterministic rendering used by every characterization emitter.
    module Support
      module_function

      def header(target, kind)
        [
          "# frozen_string_literal: true",
          "",
          "# Generated by branchout #{VERSION}. Characterization #{kind} for discovered inputs.",
          "# target: #{target.display_path}",
          "# entry: #{target.entry}"
        ]
      end

      def relative_require(destination, target_path)
        from = Pathname.new(File.expand_path(File.dirname(destination)))
        to = Pathname.new(File.expand_path(target_path))
        relative = to.relative_path_from(from).to_s.tr("\\", "/")
        relative.start_with?(".") ? relative : "./#{relative}"
      end

      # The statements that build the receiver, and the entry call. With no
      # setup calls the receiver is built inline and there is no statement.
      # A name in +private_calls+ (the entry, or new) is called through send,
      # as explore called it.
      def arrange(target, input, private_calls: [])
        receiver = if target.singleton
          target.const_name
        elsif input.receiver || private_calls.include?(:new)
          call_text(target.const_name, :new, input.receiver ? argument_list(input.receiver) : "", private_calls)
        else
          "#{target.const_name}.new"
        end
        call = ->(on) { call_text(on, target.method_name, argument_list(input), private_calls) }
        return [[], call.(receiver)] if input.setup.empty?

        name = receiver_name(target)
        statements = ["#{name} = #{receiver}"]
        input.setup.each do |setup_call|
          statements << "#{name}.#{setup_call.method_name}(#{argument_list(setup_call.arguments)})"
        end
        [statements, call.(name)]
      end

      def call_text(on, method_name, arguments, private_calls)
        return "#{on}.#{method_name}(#{arguments})" unless private_calls.include?(method_name)

        "#{on}.send(#{[method_name.inspect, *(arguments unless arguments.empty?)].join(", ")})"
      end

      # The class name in snake case, as a reader would name the object.
      def receiver_name(target)
        name = target.const_name.split("::").last
                     .gsub(/([A-Z]+)([A-Z][a-z])/, '\1_\2')
                     .gsub(/([a-z\d])([A-Z])/, '\1_\2')
                     .downcase
        RESERVED_NAMES.include?(name) ? "subject" : name
      end

      RESERVED_NAMES = %w[
        alias and begin break case class def defined do else elsif end ensure false for if in
        module next nil not or redo rescue retry return self super then true undef unless until
        when while yield error
      ].freeze

      def argument_list(input)
        args = input.args.map { |value| ruby_literal(value, mutable: true) }
        kwargs = input.kwargs.keys.sort.map { |key|
          "#{keyword_literal(key)}: #{ruby_literal(input.kwargs[key], mutable: true)}"
        }
        (args + kwargs).join(", ")
      end

      # An emitted test has frozen_string_literal, so a +mutable+ string is
      # written with a leading + to match the copy the explore run passed.
      def ruby_literal(value, mutable: false)
        case value
        when nil then "nil"
        when true then "true"
        when false then "false"
        when Integer then value.to_s
        when Float then Canon.format_float(value)
        when String then mutable ? "+#{value.inspect}" : value.inspect
        when Symbol then value.inspect
        when Array
          "[#{value.map { |item| ruby_literal(item, mutable: mutable) }.join(", ")}]"
        when Hash
          # Insertion order, as the value prints: a failure diff then lines
          # up key by key, and Hash equality ignores order anyway.
          "{#{value.map { |key, item| "#{ruby_literal(key)} => #{ruby_literal(item, mutable: mutable)}" }.join(", ")}}"
        else
          raise Error, "cannot emit a literal for #{value.class}"
        end
      end

      def literal?(value)
        case value
        when nil, true, false, Integer, String, Symbol then true
        when Float then value.finite?
        when Array then value.all? { |item| literal?(item) }
        when Hash then value.all? { |key, item| literal?(key) && literal?(item) }
        else false
        end
      end

      # A value with no Ruby literal, such as a Set or a Struct, is pinned by
      # its class. An anonymous class has no stable name, so its nearest
      # named superclass stands in.
      def class_literal(value)
        value.class.ancestors.find { |mod| mod.is_a?(Class) && mod.name }.name
      end

      def keyword_literal(key)
        text = key.to_s
        return text if text.match?(/\A[A-Za-z_][A-Za-z0-9_]*\z/)

        text.inspect
      end

      def class_name_for(target)
        const_part = target.const_name.gsub("::", "")
        method_part = target.method_name.to_s.gsub("?", "P").gsub("!", "B").gsub("=", "E")
        method_part = method_part.split("_").map { |word| word.sub(/\A[a-z]/, &:upcase) }.join
        "#{const_part}#{method_part}CharacterizationTest"
      end

      # Minitest method names: the input's values, then what the test pins.
      # A digest of the input keeps each name unique and unchanged when other
      # inputs are added; a digest collision falls back to a counter.
      def test_names(pins)
        names = pins.map do |pin|
          words = ["test", clip(input_words(pin.input), 40), clip(outcome_words(pin), 30)]
          words << Digest::SHA256.hexdigest(pin.input.canonical)[0, 6]
          words.reject(&:empty?).join("_")
        end
        seen = Hash.new(0)
        names.map { |name| (seen[name] += 1) == 1 ? name : "#{name}_#{seen[name]}" }
      end

      # RSpec descriptions: the input as the report prints it, then what the
      # test pins.
      def description(pin)
        outcome = if pin.error
          "raises #{pin.error.class_name}"
        elsif literal?(pin.value)
          text = ruby_literal(pin.value)
          "returns #{text.length > 60 ? "#{text[0, 57]}..." : text}"
        else
          "returns a #{class_literal(pin.value)}"
        end
        "#{pin.input.text} #{outcome}"
      end

      def input_words(input)
        words = value_words(input.args) + value_words(input.kwargs)
        words += ["new", *input_words(input.receiver)] if input.receiver
        input.setup.each { |call| words += [call.method_name, *input_words(call.arguments)] }
        words
      end

      def outcome_words(pin)
        return ["raises", *snake_words(pin.error.class_name)] if pin.error
        return ["returns", *snake_words(class_literal(pin.value))] unless literal?(pin.value)

        ["returns", *shape_words(pin.value)]
      end

      # A Hash is named by its keys and an Array of collections by its size,
      # so the start of a long value does not fill the name.
      def shape_words(value)
        case value
        when {}, [] then ["empty", value.is_a?(Hash) ? "hash" : "array"]
        when Hash then ["hash", *value.keys.map(&:to_s)]
        when Array
          value.any? { |item| item.is_a?(Hash) || item.is_a?(Array) } ? ["array", "of", value.length.to_s] : value_words(value)
        else value_words(value)
        end
      end

      def value_words(value)
        case value
        when Array then value.flat_map { |item| value_words(item) }
        when Hash then value.flat_map { |key, item| [key.to_s, *value_words(item)] }
        when nil then ["nil"]
        when "" then ["empty"]
        when /\A\s+\z/ then ["blank"]
        when /\A[^A-Za-z0-9]+\z/ then ["text"]
        when Numeric then [value.to_s.sub(/\A-/, "neg")]
        else [value.to_s]
        end
      end

      def snake_words(class_name)
        [class_name.gsub("::", "_").gsub(/([a-z\d])([A-Z])/, '\1_\2')]
      end

      # Joins words into identifier characters, at most +limit+ long, cut
      # between words. Only a first word longer than +limit+ is cut inside.
      def clip(words, limit)
        tokens = words.join("_").downcase.split(/[^a-z0-9]+/).reject(&:empty?)
        return tokens.first.to_s[0, limit] if tokens.first.to_s.length > limit

        tokens.each_with_object([]) { |token, kept|
          break kept if (kept + [token]).join("_").length > limit

          kept << token
        }.join("_")
      end

      def cover_comment(pin, indent)
        return [] if pin.arm_ids.empty?

        ["#{indent}# covers: #{pin.arm_ids.join(", ")}"]
      end

      def write_file(destination, content)
        FileUtils.mkdir_p(File.dirname(destination))
        File.write(destination, content)
      end
    end
  end
end
